  private I18n() {}

  private static SharedPreferences prefs(Context c) { return c.getSharedPreferences("cammicgo_ui", Context.MODE_PRIVATE); }

  /** Index of the chosen language; defaults to the phone language, else English. */
  public static int index(Context c) {
    String code = prefs(c).getString("lang", null);
    if (code == null) code = Locale.getDefault().getLanguage();
    for (int i = 0; i < CODES.length; i++) if (CODES[i].equals(code)) return i;
    return 0;
  }

  public static String code(Context c) { return CODES[index(c)]; }
  public static boolean rtl(Context c) { return "ar".equals(code(c)); }
  public static void set(Context c, String code) { prefs(c).edit().putString("lang", code).apply(); }

  public static String t(Context c, String key, Object... args) {
    String[] v = m.get(key);
    if (v == null) return key;
    String s = v[index(c)];
    return args.length == 0 ? s : String.format(Locale.ROOT, s, args);
  }

